const safe = (node) => { try { return $(node).all().map(i => i.json); } catch { return []; } };
const value = (row, key) => row[key] ?? '';
const number = (x) => Number(String(x).replace(',', '.')) || 0;

const reports = safe('Read Demand Report')
  .filter(r => value(r, 'demand_cluster (Кластер попиту)'))
  .sort((a, b) => number(value(a, 'rank (Рейтинг)')) - number(value(b, 'rank (Рейтинг)')) || number(value(b, 'demand_score (Оцінка попиту)')) - number(value(a, 'demand_score (Оцінка попиту)')))
  .slice(0, 5);
const demandRows = safe('Read Demand Analysis').filter(r => value(r, 'demand_cluster (Кластер попиту)'));
const tech = safe('Read Tech Signals')
  .filter(r => value(r, 'tech_signal_id (ID технологічного сигналу)'))
  .sort((a, b) => (number(value(b, 'technology_score (Загальна оцінка технології)')) * 100 + number(value(b, 'automation_potential_score (Потенціал автоматизації)')) * 10 + number(value(b, 'confidence_score (Рівень впевненості)'))) - (number(value(a, 'technology_score (Загальна оцінка технології)')) * 100 + number(value(a, 'automation_potential_score (Потенціал автоматизації)')) * 10 + number(value(a, 'confidence_score (Рівень впевненості)'))))
  .slice(0, 20)
  .map(r => ({ tech_signal_id: value(r, 'tech_signal_id (ID технологічного сигналу)'), technology: value(r, 'technology (Технологія)'), new_capability: value(r, 'new_capability (Нова можливість)'), business_use_case: value(r, 'business_use_case (Бізнес-застосування)').slice(0, 1000), common_integrations: value(r, 'common_integrations (Типові інтеграції)').slice(0, 500), limitations_risks: value(r, 'limitations_risks (Обмеження та ризики)').slice(0, 500), evidence_urls: value(r, 'evidence_urls (Посилання на джерела)'), technology_score: number(value(r, 'technology_score (Загальна оцінка технології)')), automation_potential: number(value(r, 'automation_potential_score (Потенціал автоматизації)')), confidence: number(value(r, 'confidence_score (Рівень впевненості)')) }));

const briefs = reports.map(report => {
  const cluster = value(report, 'demand_cluster (Кластер попиту)');
  const examples = demandRows.filter(r => value(r, 'demand_cluster (Кластер попиту)') === cluster).slice(0, 3).map(r => ({ opportunity_id: value(r, 'opportunity_id (ID можливості)'), title: value(r, 'title (Назва)').slice(0, 300), problem: value(r, 'client_problem (Проблема клієнта)').slice(0, 700), url: value(r, 'url (Посилання)'), potential_service: value(r, 'potential_service (Потенційна послуга)') }));
  return { demand: { demand_cluster: cluster, market_demand_score: number(value(report, 'demand_score (Оцінка попиту)')), demand_strength: value(report, 'demand_strength (Сила попиту)'), trend: value(report, 'trend (Тренд)'), key_client_problems: value(report, 'key_client_problems (Ключові проблеми клієнтів)').slice(0, 1200), potential_service: value(report, 'potential_service (Потенційна послуга)').slice(0, 500), examples }, tech_candidates: tech, allowed_tech_signal_ids: tech.map(t => t.tech_signal_id) };
});
return [{ json: { briefs, brief_count: briefs.length, demand_clusters_considered: reports.length, tech_signals_considered: tech.length } }];

const responseText = $json.output?.[0]?.content?.find(part => part.type === 'output_text')?.text ?? '{}';
const parsed = JSON.parse(responseText);
const brief = $('Process Each Demand Cluster').item.json.brief;
const clamp = (value) => Math.max(0, Math.min(100, Math.round(Number(value) || 0)));
const slugify = (text) => String(text || 'idea').toLowerCase().replace(/[^a-z0-9а-яіїєґ]+/gi, '-').replace(/^-+|-+$/g, '').slice(0, 80) || 'idea';
const allowed = new Set([...(brief.allowed_tech_signal_ids || []), 'demand-only']);
const now = $now.toISO();
const urls = (brief.demand.examples || []).map(x => x.url).filter(Boolean).join('\n');
const ids = (brief.demand.examples || []).map(x => x.opportunity_id).filter(Boolean).join(', ');
return (parsed.ideas || []).slice(0, 2).map((idea, index) => {
  const techId = allowed.has(idea.tech_signal_id) ? idea.tech_signal_id : 'demand-only';
  const technology = techId === 'demand-only' ? 'n8n core capabilities' : idea.technology;
  const fit = clamp(idea.technology_fit_score);
  const portfolio = clamp(idea.portfolio_potential);
  const content = clamp(idea.content_potential);
  const market = clamp(brief.demand.market_demand_score);
  const opportunity = Math.round(market * 0.45 + fit * 0.35 + portfolio * 0.10 + content * 0.10);
  const slug = slugify(idea.idea_slug || `${brief.demand.demand_cluster}-${index + 1}`);
  const key = `CO::${brief.demand.demand_cluster}::${techId}::${slug}`;
  return { json: {
    'content_opportunity_id (ID контент-можливості)': key,
    'dedupe_key (Ключ дедуплікації)': key,
    'demand_cluster (Кластер попиту)': brief.demand.demand_cluster,
    'market_demand_score (Оцінка ринкового попиту)': market,
    'demand_strength (Сила попиту)': brief.demand.demand_strength,
    'client_problem (Проблема клієнта)': brief.demand.key_client_problems,
    'evidence_opportunity_ids (ID запитів-доказів)': ids,
    'evidence_urls (Посилання на запити)': urls,
    'tech_signal_id (ID технологічного сигналу)': techId,
    'technology (Технологія)': technology,
    'technology_fit_rationale (Чому технологія підходить)': idea.technology_fit_rationale,
    'target_audience (Цільова аудиторія)': idea.target_audience,
    'n8n_automation_idea (Ідея n8n-автоматизації)': idea.n8n_automation_idea,
    'solution_architecture (Архітектура рішення)': idea.solution_architecture,
    'potential_service (Потенційна послуга)': idea.potential_service || brief.demand.potential_service,
    'technology_fit_score (Відповідність технології)': fit,
    'portfolio_potential (Потенціал портфоліо)': portfolio,
    'content_potential (Контент-потенціал)': content,
    'opportunity_score (Загальна оцінка можливості)': opportunity,
    'score_rationale (Обґрунтування оцінок)': idea.score_rationale,
    'content_angle (Контентний кут)': idea.content_angle,
    'hook (Хук)': idea.hook,
    'linkedin_post (Пост для LinkedIn)': idea.linkedin_post,
    'instagram_post (Пост для Instagram)': idea.instagram_post,
    'cta (Заклик до дії)': idea.cta,
    'visual_idea (Ідея візуалу або каруселі)': idea.visual_idea,
    'status (Статус)': 'draft',
    'generated_at (Дата генерації)': now,
    'updated_at (Дата оновлення)': now,
    '_input_tokens': Number($json.usage?.input_tokens ?? 0),
    '_output_tokens': Number($json.usage?.output_tokens ?? 0),
    '_total_tokens': Number($json.usage?.total_tokens ?? 0)
  }};
});

const safe = (node) => { try { return $(node).all(); } catch { return []; } };
const run = $('Prepare Content Run Start').first().json;
const rows = safe('Validate and Shape Content Rows');
const input = safe('Read Demand Report').filter(i => i.json['demand_cluster (Кластер попиту)']).length;
const calls = safe('Generate Content Opportunities');
const sum = (field) => rows.reduce((total, item) => total + Number(item.json[field] || 0), 0);
const inputTokens = sum('_input_tokens');
const outputTokens = sum('_output_tokens');
const totalTokens = sum('_total_tokens');
const estimatedCostUsd = Number(((inputTokens / 1000000) * 0.75 + (outputTokens / 1000000) * 4.5).toFixed(8));
const finishedAt = $now.toISO();
return [{ json: {
  'run_id (ID запуску)': run.run_id,
  'n8n_execution_id (ID виконання n8n)': String($execution.id),
  'workflow_name (Назва workflow)': $workflow.name,
  'workflow_category (Категорія workflow)': 'ai_content_strategy',
  'trigger_type (Тип запуску)': $execution.mode,
  'started_at (Час початку)': run.started_at,
  'finished_at (Час завершення)': finishedAt,
  'duration_seconds (Тривалість, сек)': Math.max(0, Math.round($now.diff(DateTime.fromISO(run.started_at), 'seconds').seconds)),
  'run_status (Статус запуску)': 'success',
  'items_input (Вхідних записів)': input,
  'items_processed (Оброблено записів)': safe('Build Content Briefs')[0]?.json.brief_count || 0,
  'items_created (Створено записів)': rows.length,
  'items_updated (Оновлено записів)': 0,
  'items_skipped (Пропущено записів)': 0,
  'items_failed (Помилок записів)': 0,
  'ai_calls (AI-викликів)': calls.length,
  'model_name (AI-модель)': 'gpt-5.4-mini',
  'input_tokens (Вхідні токени)': inputTokens,
  'output_tokens (Вихідні токени)': outputTokens,
  'total_tokens (Усього токенів)': totalTokens,
  'estimated_cost_usd (Орієнтовна вартість, USD)': estimatedCostUsd,
  'error_message (Повідомлення про помилку)': '',
  'run_metadata (Додаткові дані JSON)': JSON.stringify({ demand_clusters: safe('Build Content Briefs')[0]?.json.brief_count || 0, tech_signals: safe('Build Content Briefs')[0]?.json.tech_signals_considered || 0, formula: '0.45 market + 0.35 technology fit + 0.10 portfolio + 0.10 content' })
}}];
